    'lay.tiles': "Tuiles", 'lay.compact': "Petites tuiles", 'lay.list': "Liste", 'keys.title': "Raccourcis clavier (?)", 'help.keys': "## Partout\n- Ctrl+F ou / – chercher un compte\n- Ctrl+K – Chercher un joueur\n- Ctrl+1 … 6 – Comptes, Vue d'ensemble, Collection, Live, Historique, Outils\n- Ctrl+N – ajouter un compte, Ctrl+Maj+N – plusieurs\n- Ctrl+, – paramètres\n- F5 – actualiser les rangs\n- ? – cette liste\n- Échap – fermer / annuler la sélection\n## Comptes\n- Flèches – compte suivant (Maj : plusieurs)\n- Ctrl+A – sélectionner tous les comptes affichés\n- Entrée – se connecter\n- E ou F2 – modifier la note\n- P – profil\n- Suppr – retirer (demande d'abord)\n- Ctrl+clic, Maj+clic ou tracer un cadre – sélectionner plusieurs, puis changer note, catégorie … d'un coup",
    'add.bulk': "Ajouter plusieurs comptes", 'add.bulkSub': "Colle une liste – un compte par ligne", 'bulk.title': "Ajouter plusieurs comptes", 'bulk.hint': "Un compte par ligne : user:motdepasse, user--Nom#TAG--motdepasse, user;motdepasse;Nom#TAG;note – ou des blocs « Username: … », « Password: … », « Riot ID: … » avec une ligne vide entre les comptes. Un Riot ID seul ajoute le compte sans identifiants. Rien n'est connecté maintenant.", 'bulk.ph': "account1:motdepasse1\naccount2--Nom#EUW--motdepasse2\nNom#EUW", 'bulk.note': "Note", 'bulk.noCat': "Sans catégorie", 'bulk.btn': "Ajouter {n}", 'bulk.progress': "Ajout {i} / {n} …", 'bulk.done': "{n} comptes ajoutés.", 'bulk.doneSkip': "{n} comptes ajoutés, {k} lignes ignorées.", 'bulk.none': "Colle ou tape ta liste ci-dessus.", 'bulk.idOnly': "Riot ID seul", 'bulk.err.pass': "Mot de passe manquant", 'bulk.err.user': "Nom d'utilisateur ?", 'bulk.err.empty': "Non reconnu", 'bulk.err.twice': "En double",
    'nav.dash': "Vue d'ensemble", 'dash.title': "Vue d'ensemble", 'dash.sub': "Tous tes comptes dans un graphique – et où en est chacun", 'dash.d7': "7 jours", 'dash.d30': "30 jours", 'dash.d90': "90 jours", 'dash.all': "Tout", 'dash.games': "Parties classées", 'dash.wl': "Victoires – défaites", 'dash.wr': "Taux de victoire", 'dash.lp': "LP", 'dash.climber': "Meilleure progression", 'dash.account': "Compte", 'dash.rank': "Rang actuel", 'dash.goal': "Objectif", 'dash.noGoal': "Fixer un objectif …", 'dash.goalLeft': "encore {n} LP", 'dash.goalDone': "Atteint ✓", 'dash.active': "Dernière partie", 'dash.empty': "Pas encore de données classées. Rangs et LP sont enregistrés pour chaque compte tant que League est ouvert – connecte-toi une fois à chacun.", 'dash.chartEmpty': "Aucun changement de LP sur cette période – choisis-en une plus longue ou affiche plus de comptes.",
